// The AI node returns one item per ticket, in order: {text} on success, {error} if the call failed
// (its On Error setting is "Continue"). Matched to the settings by position, because LLM chain
// outputs don't carry item links.
const settings = $('Demo Settings (edit me)').all();
return $input.all().map((item, i) => {
  const s = settings[i].json, j = item.json;
  return { json: {
    order: i, record_id: s.record_id, source: 'demo', task: s.ticket, schema: s.json_schema,
    max_retries: s.max_retries, coerce_types: s.coerce_types, attempt: 1,
    raw_output: j.text ?? j.output ?? '', llm_error: j.error ? (j.error.message || String(j.error)) : '',
  } };
});

// Accepts raw_output (or text / output) plus schema (object or JSON string). Everything else is optional.
const j = $json;
const err = j.llm_error || j.error;
return { json: {
  order: $itemIndex, record_id: String(j.record_id ?? $itemIndex), source: j.source || 'caller', task: j.task || '',
  schema: j.schema ?? j.json_schema ?? null, max_retries: Number(j.max_retries ?? 2), coerce_types: j.coerce_types !== false,
  attempt: 1, raw_output: j.raw_output ?? j.text ?? j.output ?? '',
  llm_error: err ? (err.message || String(err)) : '',
} };

// Turns whatever the model returned into a parsed JSON value, without another AI call.
// Handles: ```json fences, <think>/<reasoning> blocks, "Thought/Action/Final Answer" agent steps,
// prose before or after the JSON, Responses-API content blocks, {"output": ...} wrappers,
// trailing commas, // comments, smart quotes, Python True/False/None and single-quoted keys.
function toText(raw, fixes) {
  if (raw === null || raw === undefined) return '';
  if (typeof raw === 'string') return raw;
  if (Array.isArray(raw) && raw.length && raw.every(b => b && typeof b === 'object' && ('text' in b || 'type' in b))) {
    fixes.push('joined content blocks'); // Responses API / Anthropic style: [{type:'output_text', text:'...'}]
    return raw.map(b => typeof b.text === 'string' ? b.text : (b.text && b.text.value) || '').join('\n');
  }
  if (typeof raw === 'object') {
    for (const k of ['text', 'output_text', 'content']) if (typeof raw[k] === 'string') { fixes.push('read .' + k); return raw[k]; }
    return { __object: raw };
  }
  return String(raw);
}
function candidates(s) { // every balanced {...} or [...] that respects strings
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const open = s[i]; if (open !== '{' && open !== '[') continue;
    const stack = []; let inStr = null, esc = false;
    for (let j = i; j < s.length; j++) {
      const c = s[j];
      if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === inStr) inStr = null; continue; }
      if (c === '"' || c === "'") { inStr = c; continue; }
      if (c === '{' || c === '[') stack.push(c);
      else if (c === '}' || c === ']') { stack.pop(); if (!stack.length) { out.push(s.slice(i, j + 1)); i = j; break; } }
    }
    if (out.length >= 20) break;
  }
  return out;
}
function lightRepair(t) {
  return t
    .replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'")
    .replace(/^\s*\/\/.*$/gm, '')
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/([{,]\s*)'([^'"\n]+?)'\s*:/g, '$1"$2":')
    .replace(/:\s*'([^'"\n]*)'(\s*[,}\]])/g, ': "$1"$2')
    .replace(/([:\[,]\s*)True(\s*[,}\]])/g, '$1true$2').replace(/([:\[,]\s*)False(\s*[,}\]])/g, '$1false$2').replace(/([:\[,]\s*)None(\s*[,}\]])/g, '$1null$2');
}
const out = [];
for (const item of $input.all()) {
  const j = item.json; const fixes = [];
  let parsed, parseError = '', text = toText(j.raw_output, fixes);
  if (j.llm_error) parseError = 'AI step failed: ' + String(j.llm_error).slice(0, 300);
  else if (text && typeof text === 'object' && text.__object) { parsed = text.__object; text = JSON.stringify(parsed); }
  else {
    let s = String(text);
    if (/<(think|thinking|reasoning)>/i.test(s)) { s = s.replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, ''); fixes.push('removed <think> block'); }
    const fa = s.lastIndexOf('Final Answer:');
    if (fa >= 0) { s = s.slice(fa + 13); fixes.push('kept only the text after Final Answer:'); }
    const fence = s.match(/```(?:json|JSON)?\s*([\s\S]*?)```/);
    if (fence) { s = fence[1]; fixes.push('stripped ``` code fence'); }
    s = s.trim();
    try { parsed = JSON.parse(s); }
    catch (e) {
      parseError = e.message;
      const cands = candidates(s).sort((a, b) => b.length - a.length);
      for (const c of cands) {
        try { parsed = JSON.parse(c); fixes.push('removed text around the JSON'); parseError = ''; break; } catch (e2) {}
        try { parsed = JSON.parse(lightRepair(c)); fixes.push('repaired JSON syntax (commas/quotes/True/None)'); parseError = ''; break; } catch (e3) { parseError = e3.message; }
      }
      if (parsed === undefined && !cands.length) parseError = !s ? 'Model output was empty' : /[\[{]/.test(s) ? 'JSON is incomplete (the output looks cut off; raise Maximum Number of Tokens)' : 'No JSON object or array found in the model output';
    }
    // A JSON string that itself contains JSON (double-encoded)
    if (typeof parsed === 'string' && /^\s*[\[{]/.test(parsed)) { try { parsed = JSON.parse(parsed); fixes.push('decoded double-encoded JSON'); } catch (e) {} }
  }
  out.push({ json: { ...j, raw_text: typeof text === 'string' ? text : JSON.stringify(text), parsed: parsed === undefined ? null : parsed,
    parse_ok: parsed !== undefined && !j.llm_error, parse_error: parseError, fixes: [...(j.fixes || []), ...fixes] }, pairedItem: item.pairedItem });
}
return out;

// Validates the parsed JSON against your JSON Schema (a practical subset: type, required, properties,
// additionalProperties, enum, items, min/max, minLength/maxLength, minItems/maxItems, pattern).
// With coerce_types on, safe fixes are applied and listed: "3" -> 3, "true" -> true, 7 -> "7",
// "Billing" -> "billing" (enum case), a single value -> [value], extra keys removed.
function typeOf(v) { return v === null ? 'null' : Array.isArray(v) ? 'array' : Number.isInteger(v) ? 'integer' : typeof v; }
function okType(v, t) { const a = typeOf(v); return t === a || (t === 'number' && a === 'integer'); }
function check(v, s, path, errs, fixes, coerce) {
  if (!s || typeof s !== 'object') return v;
  const types = s.type ? [].concat(s.type) : null;
  if (types && !types.some(t => okType(v, t))) {
    let fixed, did = false;
    if (coerce) for (const t of types) {
      if ((t === 'number' || t === 'integer') && typeof v === 'string' && v.trim() !== '' && !isNaN(Number(v)) && (t === 'number' || Number.isInteger(Number(v)))) { fixed = Number(v); did = true; break; }
      if (t === 'integer' && typeof v === 'number' && Math.abs(v - Math.round(v)) < 1e-9) { fixed = Math.round(v); did = true; break; }
      if (t === 'boolean' && typeof v === 'string' && /^(true|false|yes|no)$/i.test(v.trim())) { fixed = /^(true|yes)$/i.test(v.trim()); did = true; break; }
      if (t === 'string' && (typeof v === 'number' || typeof v === 'boolean')) { fixed = String(v); did = true; break; }
      if (t === 'array' && v !== null && v !== undefined && !Array.isArray(v)) { fixed = [v]; did = true; break; }
      if (t === 'null' && (v === '' || v === 'null')) { fixed = null; did = true; break; }
    }
    if (did) { fixes.push(`coerced ${path || 'value'} ${JSON.stringify(v)} -> ${JSON.stringify(fixed)}`); v = fixed; }
    else { errs.push(`${path || 'value'} must be ${types.join(' or ')}, got ${typeOf(v)} ${JSON.stringify(v).slice(0, 60)}`); return v; }
  }
  if (s.enum) {
    if (!s.enum.includes(v)) {
      const m = coerce && typeof v === 'string' ? s.enum.find(e => typeof e === 'string' && e.toLowerCase() === v.trim().toLowerCase()) : undefined;
      if (m !== undefined) { fixes.push(`coerced ${path} ${JSON.stringify(v)} -> ${JSON.stringify(m)}`); v = m; }
      else errs.push(`${path || 'value'} must be one of ${JSON.stringify(s.enum)}, got ${JSON.stringify(v)}`);
    }
  }
  if (typeof v === 'number') {
    if (s.minimum !== undefined && v < s.minimum) errs.push(`${path} must be >= ${s.minimum}, got ${v}`);
    if (s.maximum !== undefined && v > s.maximum) errs.push(`${path} must be <= ${s.maximum}, got ${v}`);
  }
  if (typeof v === 'string') {
    if (s.minLength !== undefined && v.length < s.minLength) errs.push(`${path} must have at least ${s.minLength} characters`);
    if (s.maxLength !== undefined && v.length > s.maxLength) errs.push(`${path} must have at most ${s.maxLength} characters`);
    if (s.pattern && !(new RegExp(s.pattern)).test(v)) errs.push(`${path} must match ${s.pattern}`);
  }
  if (Array.isArray(v)) {
    if (s.minItems !== undefined && v.length < s.minItems) errs.push(`${path} needs at least ${s.minItems} items`);
    if (s.maxItems !== undefined && v.length > s.maxItems) errs.push(`${path} allows at most ${s.maxItems} items`);
    if (s.items) v = v.map((x, i) => check(x, s.items, `${path}[${i}]`, errs, fixes, coerce));
  }
  if (typeOf(v) === 'object') {
    const props = s.properties || {};
    for (const r of s.required || []) if (!(r in v) || v[r] === undefined) errs.push(`missing required field "${path ? path + '.' : ''}${r}"`);
    for (const k of Object.keys(v)) {
      if (props[k]) v[k] = check(v[k], props[k], path ? `${path}.${k}` : k, errs, fixes, coerce);
      else if (s.additionalProperties === false) {
        if (coerce) { fixes.push(`removed extra field "${path ? path + '.' : ''}${k}"`); delete v[k]; }
        else errs.push(`unexpected field "${path ? path + '.' : ''}${k}"`);
      }
    }
  }
  return v;
}
const out = [];
for (const item of $input.all()) {
  const j = item.json; const errs = [], fixes = [...(j.fixes || [])];
  let schema = j.schema;
  if (typeof schema === 'string') { try { schema = JSON.parse(schema); } catch (e) { schema = null; errs.push('Your JSON Schema itself is not valid JSON: ' + e.message); } }
  let data = j.parsed;
  if (!j.parse_ok) errs.push(j.parse_error || 'Could not parse JSON');
  else if (schema) {
    data = JSON.parse(JSON.stringify(data));
    const wantObj = [].concat(schema.type || []).includes('object');
    // n8n's Structured Output Parser convention wraps results as {"output": {...}}; models copy it.
    if (wantObj && data && typeOf(data) === 'object' && Object.keys(data).length === 1 && 'output' in data && !(schema.properties || {}).output && typeOf(data.output) === 'object') { data = data.output; fixes.push('unwrapped {"output": ...}'); }
    if (wantObj && Array.isArray(data) && data.length === 1 && typeOf(data[0]) === 'object') { data = data[0]; fixes.push('unwrapped single-item array'); }
    data = check(data, schema, '', errs, fixes, j.coerce_types !== false);
  }
  const attempt = Number(j.attempt || 1), maxRetries = Number(j.max_retries ?? 2);
  const valid = errs.length === 0;
  const route = valid ? 'valid' : (attempt <= maxRetries ? 'retry' : 'give_up');
  out.push({ json: { ...j, schema, data: valid ? data : null, valid, errors: errs, fixes, route,
    history: [...(j.history || []), { attempt, errors: errs, fixes: fixes.slice((j.fixes || []).length) }] }, pairedItem: item.pairedItem });
}
return out;

// Tells the model exactly what was wrong, so the retry is a targeted fix instead of a re-roll.
const j = $json;
const prev = String(j.llm_error ? '(the AI step errored: ' + j.llm_error + ')' : j.raw_text || '').slice(0, 4000);
const prompt = [
  'Your previous answer could not be used.',
  'Problems found:', ...j.errors.map(e => '- ' + e), '',
  'Return ONLY one JSON value that matches this JSON Schema. No code fences, no explanation, no text before or after it.',
  JSON.stringify(j.schema), '',
  j.task ? 'Original task:\n' + String(j.task).slice(0, 4000) + '\n' : '',
  'Previous answer:', prev,
].join('\n');
return { json: { ...j, correction_prompt: prompt } };

// Carries the context forward (matched by position, like Package For Guard), counts the attempt,
// then loops back to Clean + Extract JSON.
const prompts = $('Build Correction Prompt').all();
return $input.all().map((item, i) => {
  const { correction_prompt, parsed, data, valid, errors, route, raw_text, parse_ok, parse_error, ...ctx } = prompts[i].json;
  const j = item.json;
  return { json: { ...ctx, attempt: ctx.attempt + 1,
    raw_output: j.text ?? j.output ?? '', llm_error: j.error ? (j.error.message || String(j.error)) : '' } };
});

const j = $json;
const status = j.valid ? (j.attempt > 1 ? 'ok_after_retry' : 'ok') : 'failed';
return { json: { ok: j.valid, status, data: j.data, errors: j.errors, fixes: j.fixes, attempts: j.attempt, order: j.order,
  record_id: j.record_id, source: j.source, raw_output: j.valid ? '' : String(j.raw_text || j.llm_error || '').slice(0, 2000) } };

// This is what a calling workflow receives. Use data when ok is true; errors explain a failure.
// Items finish in different passes of the repair loop, so this gathers every finished item so far,
// in the original order. The last run (the one a calling workflow gets) has all of them.
const done = [];
for (let r = 0; r <= $runIndex; r++) done.push(...$('Build Final Result').all(0, r));
return done.sort((a, b) => a.json.order - b.json.order).map(({ json: r }) => ({ json: {
  ok: r.ok, status: r.status, data: r.data, errors: r.errors, fixes: r.fixes, attempts: r.attempts, record_id: r.record_id } }));

// How often does your prompt need help? A high retry rate means the prompt or schema needs work.
const rows = $input.all().map(i => i.json).filter(r => r.status);
const n = rows.length || 1, count = s => rows.filter(r => r.status === s).length;
const tally = {};
for (const r of rows) for (const e of String(r.errors || '').split('; ').filter(Boolean)) tally[e] = (tally[e] || 0) + 1;
for (const r of rows) for (const f of String(r.fixes || '').split('; ').filter(Boolean)) tally['fixed: ' + f.replace(/ ".*$/, '')] = (tally['fixed: ' + f.replace(/ ".*$/, '')] || 0) + 1;
return [{ json: { total: rows.length,
  ok_first_try_pct: Math.round(100 * count('ok') / n), ok_after_retry_pct: Math.round(100 * count('ok_after_retry') / n),
  failed_pct: Math.round(100 * count('failed') / n),
  top_issues: Object.entries(tally).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([k, v]) => `${v}x ${k}`) } }];
